import{_ as p,C as c,o as e,c as u,a2 as a,b as o,w as s,a as l,E,a3 as A,j as t}from"./chunks/framework.CAKCj7G0.js";const m=JSON.parse('{"title":"Redis Quicklist 存储结构","description":"","frontmatter":{},"headers":[],"relativePath":"数据库/Redis/存储类型/quicklist.md","filePath":"数据库/Redis/存储类型/quicklist.md","lastUpdated":1767884110000}'),r={name:"数据库/Redis/存储类型/quicklist.md"};function B(n,i,k,z,q,h){const d=c("Mermaid");return e(),u("div",null,[i[4]||(i[4]=a('<h1 id="redis-quicklist-存储结构" tabindex="-1">Redis Quicklist 存储结构 <a class="header-anchor" href="#redis-quicklist-存储结构" aria-label="Permalink to &quot;Redis Quicklist 存储结构&quot;">​</a></h1><h2 id="quicklist-概述" tabindex="-1">quicklist 概述 <a class="header-anchor" href="#quicklist-概述" aria-label="Permalink to &quot;quicklist 概述&quot;">​</a></h2><p>quicklist 是 Redis 从 3.2 版本开始引入的数据结构，作为列表（List）类型的底层实现，它结合了 <strong>ziplist（压缩列表）</strong> 和 <strong>双向链表</strong> 的优点，解决了 ziplist 扩容效率低、双向链表内存开销大的问题。</p><p>quicklist 本质是一个双向链表，链表中的每个节点（称为 quicklistNode）不是直接存储数据，而是存储一个 ziplist。ziplist 是一种紧凑的连续内存结构，能节省内存；双向链表则解决了 ziplist 插入/删除元素时需要整体移动数据的问题。</p><p>Redis 3.2 之前，列表的底层实现是 <code>ziplist</code> 和 <code>双向链表</code> 的二选一（元素少用 ziplist，元素多用链表）。quicklist 是融合版本，无论元素多少，始终使用 quicklist，但内部自动调整 ziplist 大小。在小元素场景下，内存占用与 ziplist 接近，插入/删除性能略优（无需整体扩容）；在大元素/多元素场景下，内存占用远低于纯双向链表，迭代/修改性能基本持平。</p>',5)),(e(),o(A,null,{default:s(()=>[E(d,{id:"mermaid-15",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20subgraph%20quicklist%5Bquicklist%20%E5%8F%8C%E5%90%91%E9%93%BE%E8%A1%A8%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20Node1%5BquicklistNode%201%5D%20--%3E%20Node2%5BquicklistNode%202%5D%20--%3E%20Node3%5BquicklistNode%203%5D%0A%20%20%20%20%20%20%20%20Node2%20--%3E%20Node1%0A%20%20%20%20%20%20%20%20Node3%20--%3E%20Node2%0A%0A%20%20%20%20%20%20%20%20subgraph%20Ziplist1%5Bziplist%201%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20%20%20%20%20E1%5B%E5%85%83%E7%B4%A0A%5D%20--%3E%20E2%5B%E5%85%83%E7%B4%A0B%5D%20--%3E%20E3%5B%E5%85%83%E7%B4%A0C%5D%0A%20%20%20%20%20%20%20%20end%0A%0A%20%20%20%20%20%20%20%20subgraph%20Ziplist2%5Bziplist%202%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20%20%20%20%20E4%5B%E5%85%83%E7%B4%A0D%5D%20--%3E%20E5%5B%E5%85%83%E7%B4%A0E%5D%20--%3E%20E6%5B%E5%85%83%E7%B4%A0F%5D%0A%20%20%20%20%20%20%20%20end%0A%0A%20%20%20%20%20%20%20%20subgraph%20Ziplist3%5Bziplist%203%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20%20%20%20%20E7%5B%E5%85%83%E7%B4%A0G%5D%20--%3E%20E8%5B%E5%85%83%E7%B4%A0H%5D%20--%3E%20E9%5B%E5%85%83%E7%B4%A0I%5D%0A%20%20%20%20%20%20%20%20end%0A%0A%20%20%20%20%20%20%20%20Node1%20-.-%3E%20Ziplist1%0A%20%20%20%20%20%20%20%20Node2%20-.-%3E%20Ziplist2%0A%20%20%20%20%20%20%20%20Node3%20-.-%3E%20Ziplist3%0A%20%20%20%20end%0A"})]),fallback:s(()=>[...i[0]||(i[0]=[l(" Loading... ",-1)])]),_:1})),i[5]||(i[5]=a('<hr><h2 id="核心结构设计" tabindex="-1">核心结构设计 <a class="header-anchor" href="#核心结构设计" aria-label="Permalink to &quot;核心结构设计&quot;">​</a></h2><p>quicklist 由三个核心组成部分构成：quicklist（外层双向链表）、quicklistNode（链表节点）和 ziplist（存储实际元素）。</p><p>quicklist 作为外层双向链表，包含头节点、尾节点指针、节点数量、总元素数量等元信息。quicklistNode 是链表的单个节点，核心字段包括：<code>zl</code> 指向当前节点的 ziplist 指针、<code>prev/next</code> 指向前后节点的指针、<code>zl_bytes</code> 当前 ziplist 的字节数、<code>zl_len</code> 当前 ziplist 中的元素个数。ziplist 是紧凑的字节数组，所有元素连续存储，无冗余内存开销，适合存储少量、小尺寸的元素。</p>',4)),(e(),o(A,null,{default:s(()=>[E(d,{id:"mermaid-26",class:"mermaid",graph:"classDiagram%0A%20%20%20%20class%20quicklistNode%20%7B%0A%20%20%20%20%20%20%20%20%2Bprev%3A%20*quicklistNode%0A%20%20%20%20%20%20%20%20%2Bnext%3A%20*quicklistNode%0A%20%20%20%20%20%20%20%20%2Bzl%3A%20*ziplist%0A%20%20%20%20%20%20%20%20%2Bzl_bytes%3A%20uint32_t%0A%20%20%20%20%20%20%20%20%2Bzl_len%3A%20uint16_t%0A%20%20%20%20%20%20%20%20%2Bsize%3A%20int16_t%0A%20%20%20%20%7D%0A%0A%20%20%20%20class%20ziplist%20%7B%0A%20%20%20%20%20%20%20%20%2Bzlbytes%3A%20uint32_t%0A%20%20%20%20%20%20%20%20%2Bzltail%3A%20uint32_t%0A%20%20%20%20%20%20%20%20%2Bzllen%3A%20uint16_t%0A%20%20%20%20%20%20%20%20%2BentryX%3A%20%5B%5Dbyte%0A%20%20%20%20%20%20%20%20%2Bzlend%3A%20uint8_t%0A%20%20%20%20%7D%0A%0A%20%20%20%20quicklistNode%20%221%22%20--%3E%20%221%22%20ziplist%20%3A%20%E5%8C%85%E5%90%AB%0A"})]),fallback:s(()=>[...i[1]||(i[1]=[l(" Loading... ",-1)])]),_:1})),i[6]||(i[6]=t("p",null,"这种结构设计实现了内存与性能的平衡。如果只用 ziplist，元素少、尺寸小时内存高效，但元素增多/增大时，插入/删除需要移动大量内存数据，性能急剧下降。如果只用双向链表，插入/删除高效，但每个节点有额外指针开销（每个节点至少 16 字节），内存利用率低。quicklist 结合两者，每个节点用 ziplist 存储一批元素，既减少了链表节点的数量（降低指针开销），又保留了链表插入/删除的高效性。",-1)),i[7]||(i[7]=t("hr",null,null,-1)),i[8]||(i[8]=t("h2",{id:"关键特性",tabindex:"-1"},[l("关键特性 "),t("a",{class:"header-anchor",href:"#关键特性","aria-label":'Permalink to "关键特性"'},"​")],-1)),i[9]||(i[9]=t("p",null,"Redis 提供了两个核心配置项，可根据业务场景调整 quicklist 的行为。",-1)),i[10]||(i[10]=t("p",null,[t("strong",null,"list-max-ziplist-size"),l(" 控制每个 quicklistNode 中 ziplist 的最大大小或最大元素数。正数表示 ziplist 最多包含的元素个数（如 8 表示每个节点最多存 8 个元素）。负数表示 ziplist 的最大字节数，-1 为 4kb，-2 为 8kb，-3 为 16kb，-4 为 32kb，-5 为 64kb。")],-1)),i[11]||(i[11]=t("p",null,[t("strong",null,"list-compress-depth"),l(" 控制 quicklist 的压缩深度（使用 LZF 算法压缩 ziplist），减少冷数据的内存占用。0 表示不压缩（默认）；1 表示压缩除了头、尾节点外的所有节点；2 表示压缩除了头 2 个、尾 2 个节点外的所有节点，以此类推。")],-1)),(e(),o(A,null,{default:s(()=>[E(d,{id:"mermaid-43",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20quicklist%5B%E5%8E%8B%E7%BC%A9%E6%B7%B1%E5%BA%A6%20list-compress-depth%3D1%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20Head%5BHead%20Node%3Cbr%2F%3E%E4%B8%8D%E5%8E%8B%E7%BC%A9%5D%20--%3E%20Mid1%5BMid%20Node%201%3Cbr%2F%3ELZF%20%E5%8E%8B%E7%BC%A9%5D%20--%3E%20Mid2%5BMid%20Node%202%3Cbr%2F%3ELZF%20%E5%8E%8B%E7%BC%A9%5D%20--%3E%20Tail%5BTail%20Node%3Cbr%2F%3E%E4%B8%8D%E5%8E%8B%E7%BC%A9%5D%0A%20%20%20%20%20%20%20%20Mid1%20--%3E%20Head%0A%20%20%20%20%20%20%20%20Mid2%20--%3E%20Mid1%0A%20%20%20%20%20%20%20%20Tail%20--%3E%20Mid2%0A%20%20%20%20end%0A%0A%20%20%20%20style%20Head%20fill%3A%234CAF50%2Ccolor%3Awhite%0A%20%20%20%20style%20Tail%20fill%3A%234CAF50%2Ccolor%3Awhite%0A%20%20%20%20style%20Mid1%20fill%3A%23FF9800%2Ccolor%3Awhite%0A%20%20%20%20style%20Mid2%20fill%3A%23FF9800%2Ccolor%3Awhite%0A"})]),fallback:s(()=>[...i[2]||(i[2]=[l(" Loading... ",-1)])]),_:1})),i[12]||(i[12]=a('<p>quicklist 内部维护了 <code>count</code> 字段（总元素数），使得 <code>LLEN</code> 等操作无需遍历，直接返回，时间复杂度 O(1)。Redis 为 quicklist 实现了专用的迭代器（quicklistIter），支持双向迭代（从表头到表尾/从表尾到表头）、安全迭代（迭代过程中允许修改列表，不会因节点删除导致迭代器失效）、惰性加载（迭代到压缩节点时，才会临时解压，用完后可重新压缩，不影响内存）。</p><hr><h2 id="操作逻辑" tabindex="-1">操作逻辑 <a class="header-anchor" href="#操作逻辑" aria-label="Permalink to &quot;操作逻辑&quot;">​</a></h2><p>以列表的 <code>LPUSH</code>（左插入）和 <code>RPOP</code>（右弹出）为例说明 quicklist 的操作流程。</p><p><strong>LPUSH 操作</strong>：首先检查 quicklist 的头节点的 ziplist 是否还有空间（未达到 <code>list-max-ziplist-size</code>）。如果有空间，直接在头节点的 ziplist 头部插入元素。如果没有空间，新建一个 quicklistNode（包含空 ziplist），作为新的头节点，再插入元素。最后更新 quicklist 的 count 字段并返回操作结果。</p>',5)),(e(),o(A,null,{default:s(()=>[E(d,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E6%89%A7%E8%A1%8C%20LPUSH%20key%20value%5D%20--%3E%20B%7B%E6%A3%80%E6%9F%A5%E5%A4%B4%E8%8A%82%E7%82%B9%20ziplist%20%E6%98%AF%E5%90%A6%E6%BB%A1%EF%BC%9F%7D%0A%20%20%20%20B%20--%20%E6%9C%AA%E6%BB%A1%20--%3E%20C%5B%E7%9B%B4%E6%8E%A5%E5%9C%A8%E5%A4%B4%E8%8A%82%E7%82%B9%20ziplist%20%E5%A4%B4%E9%83%A8%E6%8F%92%E5%85%A5%E5%85%83%E7%B4%A0%5D%20--%3E%20D%5B%E6%9B%B4%E6%96%B0%20quicklist%20%E5%85%83%E4%BF%A1%E6%81%AF%5D%0A%20%20%20%20B%20--%20%E5%B7%B2%E6%BB%A1%20--%3E%20E%5B%E6%96%B0%E5%BB%BA%20quicklistNode%20%E5%B9%B6%E5%88%9D%E5%A7%8B%E5%8C%96%E7%A9%BA%20ziplist%5D%20--%3E%20F%5B%E5%B0%86%E6%96%B0%E8%8A%82%E7%82%B9%E8%AE%BE%E4%B8%BA%E5%A4%B4%E8%8A%82%E7%82%B9%5D%20--%3E%20G%5B%E6%8F%92%E5%85%A5%E5%85%83%E7%B4%A0%E5%88%B0%E6%96%B0%E5%A4%B4%E8%8A%82%E7%82%B9%20ziplist%5D%20--%3E%20D%0A"})]),fallback:s(()=>[...i[3]||(i[3]=[l(" Loading... ",-1)])]),_:1})),i[13]||(i[13]=a('<p><strong>RPOP 操作</strong>：首先检查 quicklist 的尾节点的 ziplist 是否有元素。如果有元素，直接从尾节点的 ziplist 尾部弹出元素。如果没有元素，删除该尾节点，再从新的尾节点弹出元素。如果所有节点都无元素，返回 nil。</p><p><strong>LINSERT 操作</strong>（在指定元素前后插入）：先遍历找到目标元素所在的 quicklistNode 和 ziplist 位置，检查该 ziplist 是否有空间，有则直接插入，无则拆分 ziplist 为两个节点，再插入。全程只需操作单个或两个节点，不会影响整个列表。</p><hr><h2 id="深度优化机制" tabindex="-1">深度优化机制 <a class="header-anchor" href="#深度优化机制" aria-label="Permalink to &quot;深度优化机制&quot;">​</a></h2><p>quicklistNode 内部的 ziplist 会做内存对齐处理（默认按 8 字节对齐），目的是减少内存碎片、提升 CPU 缓存命中率。CPU 读取内存时是按缓存行（通常 64 字节）批量读取的，对齐后的内存地址能让 ziplist 数据更适配缓存行，减少无效读取。内存对齐会带来少量内存冗余（最多 7 字节），但相比性能提升，这个开销是可接受的。</p><p>ziplist 存在一个经典问题：连锁更新（cascade update）。ziplist 中每个元素的长度字段是变长的（1/2/5 字节），若修改一个元素导致长度字段变化，可能触发后续所有元素的长度字段连续更新，最坏时间复杂度 O(n)。quicklist 的规避方式是：每个 quicklistNode 只存储一批元素（受 <code>list-max-ziplist-size</code> 限制），即使触发连锁更新，也只局限在单个节点的 ziplist 内，不会扩散到整个列表；单个 ziplist 元素数量/大小有限，连锁更新的影响范围被严格控制，性能损耗可忽略。</p><hr><h2 id="hash-类型为何不用-quicklist" tabindex="-1">Hash 类型为何不用 quicklist <a class="header-anchor" href="#hash-类型为何不用-quicklist" aria-label="Permalink to &quot;Hash 类型为何不用 quicklist&quot;">​</a></h2><p>Redis Hash 的底层实现规则是优先用 ziplist，当满足阈值时转为 dict（哈希表）（Redis 7.0+ 还引入了 listpack 替代 ziplist，但逻辑一致），从始至终都不会用 quicklist。触发 ziplist 转 dict 的阈值可配置：<code>hash-max-ziplist-entries</code> 表示 ziplist 中存储的键值对数量上限（默认 512）；<code>hash-max-ziplist-value</code> 表示单个键/值的字节数上限（默认 64）。</p><p>Hash 不用 quicklist 的核心原因在于访问模式完全不同。Hash 的核心操作是 <code>HGET</code>/<code>HSET</code>/<code>HDEL</code>（根据 key 快速查找/修改 value），属于随机访问，要求 O(1) 或 O(n) 但 n 极小的查找效率。quicklist 的设计目标是为 List 类型的顺序访问（<code>LPUSH</code>/<code>RPOP</code>/<code>LRANGE</code>）优化，本质是双向链表，随机访问某个元素需要遍历链表节点和 ziplist，时间复杂度 O(m+n)，效率远低于 ziplist 直接遍历。虽然 ziplist 随机查找也是 O(n)，但 Hash 使用 ziplist 时，n（键值对数量）被 <code>hash-max-ziplist-entries</code> 限制在极小范围（默认 512），实际遍历开销可忽略；且 ziplist 是连续内存，CPU 缓存命中率远高于 quicklist（离散的链表节点），实际访问速度更快。</p><p>quicklist 对 Hash 是过度设计加内存浪费。每个 quicklistNode 包含 <code>prev/next</code> 指针（至少 16 字节）、<code>zl_bytes</code>/<code>zl_len</code> 等元信息，即使只有一个节点，也比纯 ziplist 多占用十几字节内存。Hash 的使用场景是大量 Hash 存储的是少量键值对（如用户信息：name/age/phone），用 quicklist 会因链表节点的额外开销，导致内存利用率远低于 ziplist。ziplist 的优势是紧凑的连续内存，无冗余指针开销，存储少量键值对时内存效率极致，这正是 Hash 小数据场景的核心需求。</p><p>数据组织形式也不匹配。Hash 的存储需求是键值对是成对存储的，需要保证 key 和 value 的紧密关联。ziplist 中 Hash 的存储格式是 <code>[key1, value1, key2, value2, ...]</code>，连续存储且键值一一对应，遍历和解析逻辑简单。quicklist 的存储形式是以节点加 ziplist 为单位，若用 quicklist 存储 Hash，键值对可能被拆分到不同的 quicklistNode 中（比如 key1 在节点1，value1 在节点2），会彻底破坏键值的关联性，导致查找/修改逻辑极度复杂，完全违背 Hash 的设计初衷。</p><p>扩容/收缩逻辑的适配性也不同。Hash 的扩容逻辑是当 ziplist 达到阈值时，直接转为 dict（哈希表），dict 天生适配大量键值对的随机访问，时间复杂度 O(1)，是 Hash 大数据量场景的最优解。quicklist 的扩容逻辑是为 List 的追加/弹出设计的，扩容时新建节点，无法适配 Hash 从小数据量到大数据量的平滑过渡（quicklist 即使节点再多，随机访问效率也远不如 dict）。</p><p>Redis 对每种数据类型选择底层实现的核心逻辑是匹配该类型的核心操作特性，在小数据量时追求极致内存效率，大数据量时追求极致访问性能。List 的核心操作是顺序追加/弹出/范围遍历，选 quicklist 平衡内存和顺序操作性能。Hash 的核心操作是随机键值对查找/修改，小数据量选 ziplist 实现内存极致，大数据量选 dict 实现访问极致。若强行给 Hash 用 quicklist，会既损失内存效率，又损失访问性能，完全违背这一原则。</p>',14))])}const D=p(r,[["render",B]]);export{m as __pageData,D as default};
